using Microsoft.Extensions.AI;

public class SelfConsistencyEvaluator
{
    private readonly IChatClient _chatClient;
    private const int SampleCount = 5;

    public SelfConsistencyEvaluator(IChatClient chatClient)
    {
        _chatClient = chatClient;
    }

    public async Task<string> EvaluateWithConsensusAsync(string complexProblem, CancellationToken ct = default)
    {
        var prompt = $"Problem: {complexProblem}\n\n" +
                     "Think carefully step by step. Show your reasoning.\n" +
                     "On the very last line, output exactly: 'FINAL_ANSWER: <conclusion>'";

        var options = new ChatOptions
        {
            Temperature = 0.7f // Sample diverse reasoning paths
        };

        // 1. Run 5 reasoning paths in parallel
        var tasks = Enumerable.Range(0, SampleCount)
            .Select(_ => _chatClient.CompleteAsync(prompt, options, ct));

        ChatCompletion[] results = await Task.WhenAll(tasks);

        // 2. Extract answers from final line
        var answers = results
            .Select(r => ExtractFinalAnswer(r.Message.Text ?? string.Empty))
            .Where(a => !string.IsNullOrEmpty(a))
            .ToList();

        // 3. Calculate majority vote
        var majorityAnswer = answers
            .GroupBy(a => a, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(g => g.Count())
            .First();

        Console.WriteLine($"Majority consensus: {majorityAnswer.Key} ({majorityAnswer.Count()}/{SampleCount} votes)");
        return majorityAnswer.Key;
    }

    private static string ExtractFinalAnswer(string fullText)
    {
        var lines = fullText.Split('\n');
        var marker = lines.LastOrDefault(l => l.Contains("FINAL_ANSWER:"));
        return marker?.Replace("FINAL_ANSWER:", "").Trim() ?? string.Empty;
    }
}
